class ModalManager{constructor(){this.activeModals=new Set,this.setupEventListeners()}setupEventListeners(){document.addEventListener("keydown",e=>{"Escape"===e.key&&this.hideAll()}),document.addEventListener("click",e=>{if(e.target.classList.contains("modal-overlay")){const t=e.target.nextElementSibling;t&&t.id&&this.hide(t.id)}},!0)}show(e){const t=document.getElementById(e),s=document.getElementById(e+"Overlay");return!!t&&(t&&t.classList.add("show"),s&&s.classList.add("show"),this.activeModals.add(e),document.body.style.overflow="hidden",!0)}hide(e){const t=document.getElementById(e),s=document.getElementById(e+"Overlay");return!!t&&(t&&t.classList.remove("show"),s&&s.classList.remove("show"),this.activeModals.delete(e),0===this.activeModals.size&&(document.body.style.overflow=""),!0)}toggle(e){const t=document.getElementById(e);return!!t&&(t.classList.contains("show")?this.hide(e):this.show(e))}hideAll(){this.activeModals.forEach(e=>this.hide(e))}isOpen(e){return this.activeModals.has(e)}getActiveModals(){return Array.from(this.activeModals)}}window.ModalManager=new ModalManager;